import assert from "node:assert/strict";
import { test } from "node:test";

import { roundMoney } from "../../shop/money.js";
import { quote } from "../../shop/pricing.js";
import { makeShop } from "../helpers.js";

test("US tax rounds a half cent up", () => {
  const { cart } = makeShop();
  cart.add("BOOK-01", 1); // 10.00 * 8.25% = 0.825
  const q = quote(cart.items(), "US");
  assert.equal(q.tax, 83);
  assert.equal(q.total, 1682);
});

test("roundMoney rounds half-up", () => {
  assert.equal(roundMoney(181.5), 182);
  assert.equal(roundMoney(267.5), 268);
});

